function getSum(nums) {
  const MOD = 1000000007;
  const totalFor = (step) => {
    const countEnding = new Map();
    const sumEnding = new Map();
    let total = 0;
    for (const x of nums) {
      const prev = x - step;
      const count = ((countEnding.get(prev) ?? 0) + 1) % MOD;
      const sum = ((sumEnding.get(prev) ?? 0) + count * x) % MOD;
      countEnding.set(x, ((countEnding.get(x) ?? 0) + count) % MOD);
      sumEnding.set(x, ((sumEnding.get(x) ?? 0) + sum) % MOD);
      total = (total + sum) % MOD;
    }
    return total;
  };
  let singles = 0;
  for (const x of nums) {
    singles = (singles + x) % MOD;
  }
  return (totalFor(1) + totalFor(-1) - singles + MOD) % MOD;
}

