function getSum(nums) {
  // List every consecutive subsequence explicitly: each element alone, then every way to keep appending
  // a later element that is exactly one more (or, separately, one less) than the last element taken.
  const MOD = 1000000007;
  let total = 0;
  const extend = (last, value, step) => {
    for (let j = last + 1; j < nums.length; j++) {
      if (nums[j] - nums[last] === step) {
        total = (total + value + nums[j]) % MOD;
        extend(j, value + nums[j], step);
      }
    }
  };
  for (let i = 0; i < nums.length; i++) {
    total = (total + nums[i]) % MOD;
    extend(i, nums[i], 1);
    extend(i, nums[i], -1);
  }
  return total;
}

