function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  // A narrow window of values makes long rising and falling chains likely; sometimes it sits at the top of the range.
  const width = large ? 2 + Math.floor(rand() * 300) : 1 + Math.floor(rand() * 5);
  const base = rand() < 0.3 ? 100001 - width : 1 + Math.floor(rand() * (100001 - width));
  const nums = Array.from({ length: n }, () => base + Math.floor(rand() * width));
  const order = rand();
  if (order < 0.25) nums.sort((a, b) => a - b);
  else if (order < 0.4) nums.sort((a, b) => b - a);
  else if (order < 0.55) {
    // Rising then falling, like a mountain.
    nums.sort((a, b) => a - b);
    return [[...nums.filter((_, i) => i % 2 === 0), ...nums.filter((_, i) => i % 2 === 1).reverse()].slice(0, n)];
  }
  return [nums];
}
